DO $$ DECLARE def text;chunk text;pos int;BEGIN SELECT pg_get_functiondef('public.finance_schedule_prepare(uuid,date)'::regprocedure) INTO def;chunk:='INSERT INTO fixed_asset_depreciation_schedule(tenant_id,asset_id,period_year,period_month,sequence_no,scheduled_amount) SELECT t,a.id,extract(year FROM ending)::int,extract(month FROM ending)::int,greatest(1,(extract(year FROM age(ending,a.in_service_date))*12+extract(month FROM age(ending,a.in_service_date))+1)::int),amt WHERE NOT EXISTS(SELECT 1 FROM fixed_asset_depreciation_schedule WHERE tenant_id=t AND asset_id=a.id AND period_year=extract(year FROM ending) AND period_month=extract(month FROM ending));';pos:=strpos(def,chunk);IF pos=0 THEN RAISE EXCEPTION 'Depreciation integration missing';END IF;def:=left(def,pos+length(chunk)-1)||replace(substr(def,pos+length(chunk)),chunk,'');EXECUTE def;END $$;